        for ( ExecutableElement executable : elementUtils.getAllEnclosedExecutableElements( usedMapper ) ) {
            SourceMethod method = getMethod(
                usedMapperType,
                executable,
                mapperToImplement,
                mapperOptions,
                prototypeMethods );

