        public SourceMethod build() {

            if ( mappings == null ) {
                mappings = Collections.emptySet();
            }

            if ( subclassMappings == null ) {
                subclassMappings = Collections.emptySet();
            }

            MappingMethodOptions mappingMethodOptions = new MappingMethodOptions(
                mapper,
                mappings,
                iterableMapping,
                mapMapping,
                beanMapping,
                enumMappingOptions,
                valueMappings,
                subclassMappings,
