package org.mapstruct.ap.test.inheritsupermappings;

import org.mapstruct.ap.test.inheritsupermappings.erroneous.ConflictingMapper;
import org.mapstruct.ap.test.inheritsupermappings.erroneous.NoOverrideMapper;
import org.mapstruct.ap.testutil.ProcessorTest;
import org.mapstruct.ap.testutil.WithClasses;
import org.mapstruct.ap.testutil.compilation.annotation.CompilationResult;
import org.mapstruct.ap.testutil.compilation.annotation.Diagnostic;
import org.mapstruct.ap.testutil.compilation.annotation.ExpectedCompilationOutcome;

import static javax.tools.Diagnostic.Kind.ERROR;
import static org.assertj.core.api.Assertions.assertThat;

@WithClasses({ Source.class, Nested.class, Target.class })
public class InheritedSuperMappingsTest {

    @ProcessorTest
    @WithClasses(InheritedMapper.class)
    public void shouldInheritMappingsFromOverriddenMethods() {
        Source first = new Source();
        first.setValue( "inherited" );
        first.setOther( "ignored" );
        first.setNested( nested( "from first" ) );

        Source second = new Source();
        second.setValue( "expression" );
        second.setNested( nested( "from second" ) );

        Target target = InheritedMapper.INSTANCE.map( first, second );

        assertThat( target.getInherited() ).isEqualTo( "inherited" );
        assertThat( target.getSpecific() ).isNull();
        assertThat( target.getExpression() ).isEqualTo( "expression" );
        assertThat( target.getNestedValue() ).isEqualTo( "from second" );
    }

    @ProcessorTest
    @WithClasses(InheritedMapper.class)
    public void shouldKeepPropertyMeaningAndAcceptEmptySuperMappings() {
        Source source = new Source();
        source.setSource( "property" );
        source.setValue( "automatic" );

        assertThat( InheritedMapper.INSTANCE.single( source ).getPropertyName() ).isEqualTo( "property" );
        assertThat( InheritedMapper.INSTANCE.empty( source ).getValue() ).isEqualTo( "automatic" );
    }

    @ProcessorTest
    @WithClasses(NoOverrideMapper.class)
    @ExpectedCompilationOutcome(
        value = CompilationResult.FAILED,
        diagnostics = @Diagnostic(
            type = NoOverrideMapper.class,
            kind = ERROR,
            line = 17,
            message = "@BeanMapping(inheritSuperMappings = true) requires a method that overrides a mapping method."
        )
    )
    public void shouldRejectMethodWithoutOverriddenMappingMethod() {
    }

    @ProcessorTest
    @WithClasses(ConflictingMapper.class)
    @ExpectedCompilationOutcome(
        value = CompilationResult.FAILED,
        diagnostics = @Diagnostic(
            type = ConflictingMapper.class,
            kind = ERROR,
            line = 18,
            message = "Inherited mappings for target property \"value\" conflict between mapper types "
                + "org.mapstruct.ap.test.inheritsupermappings.erroneous.LeftMapper and "
                + "org.mapstruct.ap.test.inheritsupermappings.erroneous.RightMapper."
        )
    )
    public void shouldRejectMappingsFromIncomparableBranches() {
    }

    private Nested nested(String value) {
        Nested nested = new Nested();
        nested.setNestedValue( value );
        return nested;
    }
}
